// Copies the site's changelog cards (src/pages/log.html) into tracker/app/site-changelog.js, so the tracker's
// Help > Patch notes can show them on a "Site" tab next to this app's own notes (Turbozo's ask, 10-31). The
// generated file is committed; tests/sitesync.test.js re-parses the page with this same parser and fails when
// the copy drifts, so the Site tab can never go stale. Run by hand after carding a site change:
//   node scripts/sync-site-changelog.js          (write)
//   node scripts/sync-site-changelog.js --check  (exit 1 if the file would change; what the test calls)
// Version numbers are computed exactly like scripts/build.py does for the site: every card is one version,
// counted from the oldest card (0.1.0, marked data-minor); a data-minor card starts the next 0.x.0.
const fs = require("fs"), path = require("path");
const ROOT = path.join(__dirname, "..", "..");
const SRC = path.join(ROOT, "src", "pages", "log.html");
const OUT = path.join(__dirname, "..", "app", "site-changelog.js");
const SITE = "https://maplestory.scumlord.studio/"; // data-go page links are rewritten to point here (opens in the browser)

function parse(html) {
  const start = html.indexOf('<div class="changelog">');
  if (start < 0) throw new Error("no <div class=\"changelog\"> in log.html");
  let s = html.slice(start + '<div class="changelog">'.length);
  const stop = s.indexOf("</section>");
  if (stop < 0) throw new Error("no </section> after the changelog");
  s = s.slice(0, stop);

  // walk the cards; bodies may nest <ul>/<div>, so each card ends where its own <div> balance closes
  const OPEN = /<div class="card"( data-minor)?( data-t="[^"]*")?><div class="cardhead">/g;
  const cards = [];
  for (let m; (m = OPEN.exec(s));) {
    let depth = 2, i = m.index + m[0].length;
    while (depth > 0) {
      const next = /<\/?div\b/.exec(s.slice(i));
      if (!next) throw new Error("unbalanced card div starting at offset " + m.index + " (a card never closes)");
      const at = i + next.index;
      depth += next[0] === "</div" ? -1 : 1;
      i = at + next[0].length;
    }
    const inner = s.slice(m.index + m[0].length, i - "</div>".length);
    const headEnd = inner.indexOf("</div>"); // cardhead holds only h3 + an optional pill span, never a div
    if (headEnd < 0) throw new Error("cardhead never closes at offset " + m.index);
    const head = inner.slice(0, headEnd), body = inner.slice(headEnd + "</div>".length).trim();
    const h3 = /<h3>([\s\S]*?)<\/h3>/.exec(head);
    if (!h3 || !h3[1].trim()) throw new Error("card at offset " + m.index + " has an empty <h3>");
    const pill = head.slice(h3[0].length).replace(/<[^>]*>/g, "").trim() || null;
    if (!m[2]) throw new Error("card at offset " + m.index + " has no data-t (run scripts/build.py to stamp it)");
    if (/<script/i.test(body)) throw new Error("card at offset " + m.index + " contains a <script>");
    const t = m[2].replace(' data-t="', "").replace(/"$/, "");
    if (Number.isNaN(Date.parse(t))) throw new Error("card at offset " + m.index + " has an unparsable data-t: " + t);
    // in-page site links (href="#" data-go="page") become real links to the live site; the tracker opens them in the browser
    const link = body
      .replace(/href="#" data-go="([a-z]+)"/gi, 'href="' + SITE + '#g=$1" target="_blank" rel="noopener"')
      .replace(/data-go="([a-z]+)" href="#"/gi, 'target="_blank" rel="noopener" href="' + SITE + '#g=$1"');
    cards.push({ minor: !!m[1], t, h3: h3[1].trim(), pill, body: link });
  }
  if (cards.length < 2) throw new Error("only " + cards.length + " cards found — parser out of step with log.html");
  // position decides the version number, so order matters — but the page ships with a few known inversions where
  // retro-carded entries sit at their historical slot (e.g. the 10-29 "Game update v1.1.0 data" card under the
  // 10-27 cards; moving them would renumber published versions, which site.md warns against). Warn, don't fail.
  for (let k = 1; k < cards.length; k++)
    if (Date.parse(cards[k].t) > Date.parse(cards[k - 1].t)) console.error("note: log.html card order inverts at " + cards[k].t + " (" + cards[k].h3.replace(/<[^>]*>/g, "") + ")");

  // build.py's version walk, verbatim: oldest card first, data-minor starts the next 0.x.0, everything else patches
  if (!cards[cards.length - 1].minor) throw new Error("oldest changelog card must be data-minor (0.1.0), like build.py asserts");
  let mi = 0, pa = 0;
  const vers = [];
  for (const c of [...cards].reverse()) { if (c.minor) { mi++; pa = 0; } else pa++; vers.push("0." + mi + "." + pa); }
  vers.reverse();
  return cards.map((c, k) => [vers[k], c.t, c.h3, c.pill, c.body]);
}

function render(records) {
  return '// GENERATED by tracker/scripts/sync-site-changelog.js from src/pages/log.html — the site\'s changelog cards for\n' +
    '// the tracker\'s Help > Patch notes "Site" tab. Edit the site page, then re-run the script; tests/sitesync.test.js\n' +
    '// fails when this copy drifts. Newest first: [site version, data-t, card title, pill label or null, card body html].\n' +
    '(function (root){\n  const LOG = [\n' +
    records.map(r => "    " + JSON.stringify(r)).join(",\n") + "\n" +
    '  ];\n  if (typeof module !== "undefined" && module.exports) module.exports = LOG; else root.SiteChangelog = LOG;\n' +
    '})(typeof window !== "undefined" ? window : globalThis);\n';
}

module.exports = { parse, render, SRC, OUT };

if (require.main === module) {
  const records = parse(fs.readFileSync(SRC, "utf8"));
  const out = render(records);
  if (process.argv.includes("--check")) {
    const cur = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
    if (cur !== out) { console.error("site-changelog.js is out of date with src/pages/log.html — run: node scripts/sync-site-changelog.js"); process.exit(1); }
    console.log("site-changelog.js is in step with the site (" + records.length + " cards, latest v" + records[0][0] + ")");
  } else {
    fs.writeFileSync(OUT, out);
    console.log("wrote app/site-changelog.js — " + records.length + " site cards, latest v" + records[0][0]);
  }
}
